#include "rpg/battle.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;
void check(bool v,const char* message){if(!v){throw std::runtime_error(message);}}
int main(){try{
 BattleRules rules;rules.combat_model=resolution::CombatModel::FunnelV1;
 Definition a{"A",Team::A,1000,100,100},b{"B",Team::B,1000,1,90};a.stats.block=0;b.stats.block=0;
 EffectDefinition bleed{EffectKind::Bleed,0,2};bleed.irresistible=true;
 rules.skills={{"bleed","A",0,TargetRule::Enemy,{bleed}}};
 Battle battle({a,b},rules);auto applied=battle.apply({"A",ActionType::Skill,"B","bleed"});check(applied.accepted()&&battle.find("B")->health==950,"first start tick");check(battle.find("B")->statuses.front().remaining==1,"decrement once");check(battle.apply({"B",ActionType::Attack,"A"}).accepted()&&battle.find("B")->health==950,"not at end");check(battle.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&battle.find("B")->health==850,"independent reapplication");check(battle.find("B")->statuses.size()==1,"expired first instance");
 rules.skills[0].effects={bleed,bleed,bleed,bleed};Battle stacks({a,b},rules);auto stacked=stacks.apply({"A",ActionType::Skill,"B","bleed"});check(stacked.accepted()&&stacks.find("B")->health==850&&stacks.find("B")->statuses.size()==3,"three per kind");check(std::ranges::any_of(stacked.events,[](const Event& e){return e.type==EventType::StackLimitReached;}),"cap visible");
 EffectDefinition poison{EffectKind::Poison,0,2};poison.irresistible=true;rules.skills[0].effects={poison};b.max_health=1000000;b.is_boss=true;Battle boss({a,b},rules);check(boss.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&boss.find("B")->health==999900,"boss poison cap");b.is_boss=false;Battle normal({a,b},rules);check(normal.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&normal.find("B")->health==960000,"four percent");
 b.max_health=1000;b.stats.defense=100000;b.stats.mitigation=10000;b.stats.block=10000;b.stats.special_block_cap=true;b.stats.invincible=true;rules.skills[0].effects={bleed};Battle invincible({a,b},rules);check(invincible.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&invincible.find("B")->health==1000&&invincible.find("B")->statuses.front().remaining==1,"invincible consumes duration");b.stats.invincible=false;InitialRuntime shield{"B",90,{{EffectKind::StandardShield,3,TickPolicy::NaturalOnly,0,30}}, {}};Battle protectedBattle({a,b},rules,{}, {shield});check(protectedBattle.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&protectedBattle.find("B")->health==980,"true dot shield then HP");
 b.stats={};b.stats.block=0;EffectDefinition extra{EffectKind::ExtraTurn};bleed.duration=3;rules.skills[0].effects={bleed,extra};Battle extras({a,b},rules);check(extras.apply({"A",ActionType::Skill,"B","bleed"}).accepted()&&extras.snapshot().turn_kind==TurnKind::Extra&&extras.find("B")->health==950,"extra start tick");check(extras.apply({"B",ActionType::Attack,"A"}).accepted()&&extras.find("B")->health==900,"natural follows extra");
 rules.skills.clear();Status dot{EffectKind::Bleed,2,TickPolicy::EveryTurn,0,50};dot.source_id="A";InitialRuntime runtime{"B",200,{dot,{EffectKind::Stun,2,TickPolicy::NaturalOnly,0}}, {}};b.speed=200;Battle stunned({a,b},rules,{}, {runtime});check(stunned.find("B")->health==950&&stunned.current_actor_blocked(),"tick before incapacitated action");check(stunned.initial_events().front().type==EventType::PeriodicDamage,"initial events retained");
 a.max_health=10;b.max_health=10;runtime.statuses={dot,{EffectKind::DeathExplosion,2,TickPolicy::NaturalOnly,0,100}};Battle lethal({a,b},rules,{}, {runtime});check(lethal.phase()==Phase::Finished&&lethal.winner()==Team::A,"FIFO explosion and causal victory");check(lethal.initial_events().back().type==EventType::BattleFinished,"terminal last");
 a.max_health=1000;b.max_health=1000;runtime.statuses={dot,{EffectKind::AutoRevive,2,TickPolicy::NaturalOnly,0,100}};Battle revived({a,b},rules,{{"A",1000},{"B",10}}, {runtime});check(revived.phase()==Phase::Running&&revived.find("B")->health==100,"revive before victory");
 a.attack=1;b.speed=90;poison.duration=2;rules.skills={{"poison","A",0,TargetRule::Enemy,{poison}}};b.max_health=1;Battle minimum({a,b},rules);check(minimum.apply({"A",ActionType::Skill,"B","poison"}).accepted()&&minimum.phase()==Phase::Finished,"minimum one");
 Definition deadSource{"S",Team::A,100,100,10},survivor{"C",Team::A,100,1,5},carrier{"T",Team::B,1000,1,200};Status orphan{EffectKind::Poison,2,TickPolicy::EveryTurn,0,7};orphan.source_id="S";Battle sourceGone({deadSource,survivor,carrier},BattleRules{},{{"S",0},{"C",100},{"T",1000}},{{"T",200,{orphan},{}}});check(sourceGone.find("T")->health==960,"dead source retained without recalculation");
 BattleRules technical;technical.combat_model=resolution::CombatModel::FunnelV1;technical.max_consequence_events=1;Status finalDot{EffectKind::Bleed,1,TickPolicy::EveryTurn,0,50};finalDot.source_id="S";InitialRuntime terminalRuntime{"T",200,{finalDot,{EffectKind::DeathExplosion,2,TickPolicy::NaturalOnly,0,100}}, {}};deadSource.max_health=10;carrier.max_health=10;Battle bounded({deadSource,carrier},technical,{}, {terminalRuntime});check(bounded.phase()==Phase::Finished&&bounded.end_reason()==EndReason::TechnicalLimit&&bounded.initial_events().back().type==EventType::BattleFinished,"technical FIFO keeps terminal last");
 resolution::DamageInput pureDot;pureDot.base=9;pureDot.kind=resolution::DamageKind::TrueDot;pureDot.guarding=true;pureDot.attacker.miss=10000;pureDot.attacker.damage_bonus=10000;pureDot.defender.block=10000;pureDot.defender.mitigation=10000;pureDot.defender.defense=100000;check(resolution::calculate_damage(pureDot,{}).amount==9,"fixed DoT bypasses mitigation guard miss and generic bonus");
 std::cout<<"REG_PERIODIC_TESTS_RESULT passed=13 total=13\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
